//! Real-world benchmark with actual fastembed embeddings (BGE-small-en-v1.5, 384-dim).
//!
//! Requires: /tmp/synapsedb_realbench.jsonl (generated by gen_realbench_data.py)
//!
//! Run:
//!   cargo run --example realworld_bench -p synapsedb-core --features turbo --release

use std::fs::File;
use std::io::{BufRead, BufReader};
use std::time::Instant;

use synapsedb_core::turbo::binary::BinaryIndex;
use synapsedb_core::turbo::matryoshka::MatryoshkaConfig;
use synapsedb_core::turbo::ndarray_search::NdArraySearch;
use synapsedb_core::turbo::quantize::QuantizedSearch;
use synapsedb_core::{PutRequest, Store};

#[derive(Debug, Clone, serde::Deserialize)]
struct Doc {
    id: i64,
    #[allow(dead_code)]
    title: String,
    text: String,
    embedding: Vec<f32>,
}

fn load_docs(path: &str) -> Vec<Doc> {
    let file = File::open(path).expect("open jsonl");
    let reader = BufReader::new(file);
    reader
        .lines()
        .map(|l| serde_json::from_str(&l.unwrap()).expect("parse json"))
        .collect()
}

fn build_store(docs: &[Doc]) -> tempfile::NamedTempFile {
    let tmp = tempfile::NamedTempFile::new().unwrap();
    let mut store = Store::open(tmp.path()).unwrap();

    eprintln!("Inserting {} documents into SQLite...", docs.len());
    let start = Instant::now();
    for doc in docs {
        store
            .put(&PutRequest {
                title: Some(doc.title.clone()),
                text: doc.text.clone(),
                embedding: Some(doc.embedding.clone()),
                ..Default::default()
            })
            .unwrap();
    }
    eprintln!("  Inserted in {:?}", start.elapsed());
    tmp
}

fn recall_at_k(ground_truth: &[i64], results: &[(i64, f32)], k: usize) -> f32 {
    let gt_set: std::collections::HashSet<_> = ground_truth[..k.min(ground_truth.len())].iter().collect();
    let res_ids: Vec<i64> = results.iter().take(k).map(|(id, _)| *id).collect();
    let overlap = res_ids.iter().filter(|id| gt_set.contains(id)).count();
    overlap as f32 / k as f32
}

fn benchmark_search(
    name: &str,
    nd: &NdArraySearch,
    quantized: &QuantizedSearch,
    matryoshka: &synapsedb_core::turbo::matryoshka::MatryoshkaSearch,
    binary: &BinaryIndex,
    queries: &[(i64, Vec<f32>)],
    k: usize,
) {
    eprintln!("\n=== {} ===", name);

    // Ground truth: f32 ndarray search
    let mut gt_results: Vec<Vec<i64>> = Vec::with_capacity(queries.len());
    let start = Instant::now();
    for (_, q) in queries {
        gt_results.push(nd.search(q, k).iter().map(|(id, _)| *id).collect());
    }
    let f32_time = start.elapsed().as_secs_f64() / queries.len() as f64;

    // SIMD f32
    let start = Instant::now();
    let mut simd_results = Vec::with_capacity(queries.len());
    for (_, q) in queries {
        simd_results.push(nd.search_simd(q, k).iter().map(|(id, _)| *id).collect::<Vec<_>>());
    }
    let simd_time = start.elapsed().as_secs_f64() / queries.len() as f64;
    let simd_recall: f32 = queries
        .iter()
        .enumerate()
        .map(|(i, _)| recall_at_k(&gt_results[i], &nd.search_simd(&queries[i].1, k), k))
        .sum::<f32>()
        / queries.len() as f32;

    // Quantized i8
    let start = Instant::now();
    let mut q_results = Vec::with_capacity(queries.len());
    for (_, q) in queries {
        q_results.push(quantized.search(q, k).iter().map(|(id, _)| *id).collect::<Vec<_>>());
    }
    let q_time = start.elapsed().as_secs_f64() / queries.len() as f64;
    let q_recall: f32 = queries
        .iter()
        .enumerate()
        .map(|(i, _)| recall_at_k(&gt_results[i], &quantized.search(&queries[i].1, k), k))
        .sum::<f32>()
        / queries.len() as f32;

    // Matryoshka funnel
    let start = Instant::now();
    let mut m_results = Vec::with_capacity(queries.len());
    for (_, q) in queries {
        m_results.push(matryoshka.funnel_search(q, k).iter().map(|(id, _)| *id).collect::<Vec<_>>());
    }
    let m_time = start.elapsed().as_secs_f64() / queries.len() as f64;
    let m_recall: f32 = queries
        .iter()
        .enumerate()
        .map(|(i, _)| recall_at_k(&gt_results[i], &matryoshka.funnel_search(&queries[i].1, k), k))
        .sum::<f32>()
        / queries.len() as f32;

    // Binary two-phase (overselect=5 — tuned optimal on real data)
    let start = Instant::now();
    let mut b_results = Vec::with_capacity(queries.len());
    for (_, q) in queries {
        b_results.push(binary.search_twophase(q, k, 5).iter().map(|(id, _)| *id).collect::<Vec<_>>());
    }
    let b_time = start.elapsed().as_secs_f64() / queries.len() as f64;
    let b_recall: f32 = queries
        .iter()
        .enumerate()
        .map(|(i, _)| recall_at_k(&gt_results[i], &binary.search_twophase(&queries[i].1, k, 5), k))
        .sum::<f32>()
        / queries.len() as f32;

    println!(
        "{},{},{:.3},{:.3},{:.3},{:.3},{:.3},{:.3},{:.3},{:.3},{:.3}",
        name,
        queries.len(),
        f32_time * 1e6,
        simd_time * 1e6,
        q_time * 1e6,
        m_time * 1e6,
        b_time * 1e6,
        simd_recall,
        q_recall,
        m_recall,
        b_recall,
    );
}

fn main() {
    const K: usize = 10;
    const JSONL_PATH: &str = "/tmp/synapsedb_realbench.jsonl";

    eprintln!("SynapseDB Real-World Benchmark");
    eprintln!("==============================");
    eprintln!("Loading documents from {}...", JSONL_PATH);

    let docs = load_docs(JSONL_PATH);
    eprintln!("Loaded {} documents", docs.len());

    let tmp = build_store(&docs);

    eprintln!("\nBuilding in-memory indices...");
    let start = Instant::now();
    let nd = NdArraySearch::from_sqlite(tmp.path()).unwrap();
    eprintln!("  NdArraySearch: {:?}", start.elapsed());

    let start = Instant::now();
    let quantized = nd.to_quantized();
    eprintln!("  QuantizedSearch: {:?}", start.elapsed());

    let start = Instant::now();
    let matryoshka = nd.to_matryoshka(MatryoshkaConfig::default());
    eprintln!("  MatryoshkaSearch: {:?}", start.elapsed());

    let start = Instant::now();
    let binary = nd.to_binary(true);
    eprintln!("  BinaryIndex: {:?}", start.elapsed());

    // Use every 50th document as query (100 queries for 5000 docs)
    let query_indices: Vec<usize> = (0..docs.len()).step_by(50).collect();
    let queries: Vec<(i64, Vec<f32>)> = query_indices
        .iter()
        .map(|&i| (docs[i].id, docs[i].embedding.clone()))
        .collect();

    eprintln!("\nUsing {} documents as queries (k={})", queries.len(), K);

    println!("\ncorpus,n_queries,f32_us,simd_us,quant_us,matry_us,binary_us,simd_recall,quant_recall,matry_recall,binary_recall");

    benchmark_search("realworld-5k", &nd, &quantized, &matryoshka, &binary, &queries, K);

    // Subset benchmarks for scaling analysis
    if docs.len() >= 1000 {
        let subset_1k: Vec<_> = docs.iter().take(1000).cloned().collect();
        let tmp1k = build_store(&subset_1k);
        let nd1k = NdArraySearch::from_sqlite(tmp1k.path()).unwrap();
        let q1k = nd1k.to_quantized();
        let m1k = nd1k.to_matryoshka(MatryoshkaConfig::default());
        let b1k = nd1k.to_binary(true);
        let queries_1k: Vec<_> = (0..subset_1k.len()).step_by(50)
            .map(|i| (subset_1k[i].id, subset_1k[i].embedding.clone()))
            .collect();
        benchmark_search("realworld-1k", &nd1k, &q1k, &m1k, &b1k, &queries_1k, K);
    }

    if docs.len() >= 500 {
        let subset_500: Vec<_> = docs.iter().take(500).cloned().collect();
        let tmp500 = build_store(&subset_500);
        let nd500 = NdArraySearch::from_sqlite(tmp500.path()).unwrap();
        let q500 = nd500.to_quantized();
        let m500 = nd500.to_matryoshka(MatryoshkaConfig::default());
        let b500 = nd500.to_binary(true);
        let queries_500: Vec<_> = (0..subset_500.len()).step_by(50)
            .map(|i| (subset_500[i].id, subset_500[i].embedding.clone()))
            .collect();
        benchmark_search("realworld-500", &nd500, &q500, &m500, &b500, &queries_500, K);
    }

    eprintln!("\nBenchmark complete.");
}
